// Every product image used on the site. All files in /public/product are privacy-safe copies
// generated by scripts/sanitize-screenshots.mjs. Replace them there, not here.
export type Shot = { src: string; alt: string; width: number; height: number; title?: string };

const webShot = (name: string, width: number, height: number, title: string, alt: string): Shot => ({
  src: `/product/${name}.png`,
  width,
  height,
  title,
  alt,
});
const phoneShot = (name: string, alt: string): Shot => ({
  src: `/product/${name}.png`,
  width: 720,
  height: 1456,
  alt,
});

